import pandas as pd
from datetime import timedelta

def run(inputs: dict) -> dict:
    df = inputs["app_events"].copy()

    df = df.sort_values(["user_id", "event_ts", "event_id"], kind="mergesort")

    results = []

    thirty_min = timedelta(minutes=30)

    for user_id, group in df.groupby("user_id", sort=False):
        open_session = None  # dict with session_num, session_start, last_activity_ts, event_count, heartbeat_count
        session_num_counter = 0

        for row in group.itertuples(index=False):
            event_ts = row.event_ts
            event_type = row.event_type

            if event_type in ("view", "click", "logout"):
                # activity event
                starts_new = False
                if open_session is None:
                    starts_new = True
                else:
                    delta = event_ts - open_session["last_activity_ts"]
                    if delta > thirty_min:
                        starts_new = True

                if starts_new:
                    # close any existing open session first (shouldn't normally happen
                    # since we only have one open at a time, but handle defensively)
                    if open_session is not None:
                        results.append({
                            "user_id": user_id,
                            "session_num": open_session["session_num"],
                            "session_start": open_session["session_start"],
                            "session_end": open_session["last_activity_ts"],
                            "event_count": open_session["event_count"],
                            "heartbeat_count": open_session["heartbeat_count"],
                        })
                    session_num_counter += 1
                    open_session = {
                        "session_num": session_num_counter,
                        "session_start": event_ts,
                        "last_activity_ts": event_ts,
                        "event_count": 1,
                        "heartbeat_count": 0,
                    }
                else:
                    open_session["event_count"] += 1
                    open_session["last_activity_ts"] = event_ts

                if event_type == "logout":
                    results.append({
                        "user_id": user_id,
                        "session_num": open_session["session_num"],
                        "session_start": open_session["session_start"],
                        "session_end": open_session["last_activity_ts"],
                        "event_count": open_session["event_count"],
                        "heartbeat_count": open_session["heartbeat_count"],
                    })
                    open_session = None

            elif event_type == "heartbeat":
                if open_session is not None:
                    delta = event_ts - open_session["last_activity_ts"]
                    if delta <= thirty_min:
                        open_session["event_count"] += 1
                        open_session["heartbeat_count"] += 1
                    # else dropped
                # else dropped (no open session)

            else:
                # unknown event type, ignore (not specified)
                pass

        # end of user's events: finalize any open session
        if open_session is not None:
            results.append({
                "user_id": user_id,
                "session_num": open_session["session_num"],
                "session_start": open_session["session_start"],
                "session_end": open_session["last_activity_ts"],
                "event_count": open_session["event_count"],
                "heartbeat_count": open_session["heartbeat_count"],
            })
            open_session = None

    out_cols = ["user_id", "session_num", "session_start", "session_end",
                "event_count", "heartbeat_count"]

    if results:
        out_df = pd.DataFrame(results, columns=out_cols)
    else:
        out_df = pd.DataFrame(columns=out_cols)

    out_df["user_id"] = out_df["user_id"].astype("int64")
    out_df["session_num"] = out_df["session_num"].astype("int64")
    out_df["event_count"] = out_df["event_count"].astype("int64")
    out_df["heartbeat_count"] = out_df["heartbeat_count"].astype("int64")

    return {"user_sessions": out_df}
